#include <cassert>
#include <iostream>

// How many lots of lotSize shares it takes to hold shares (rounded up).
int lotsNeeded(int shares, int lotSize) {
    assert(lotSize > 0);
    return (shares + lotSize - 1) / lotSize;
}

int main() {
    assert(lotsNeeded(0, 100) == 0);
    assert(lotsNeeded(100, 100) == 1);
    assert(lotsNeeded(101, 100) == 2);
    assert(lotsNeeded(250, 100) == 3);
    std::cout << "lotsNeeded: 4 checks passed\n";
    return 0;
}

