#include <iostream>

int g_checks = 0;
int g_failures = 0;

// Counts a check. On a mismatch it prints the line, the code, and both values.
#define CHECK_EQ(actual, expected)                                   \
    do {                                                             \
        ++g_checks;                                                  \
        auto got = (actual);                                         \
        auto want = (expected);                                      \
        if (got != want) {                                           \
            ++g_failures;                                            \
            std::cout << "FAIL line " << __LINE__ << ": " << #actual \
                      << " is " << got << ", expected " << want << '\n'; \
        }                                                            \
    } while (0)

int spreadTicks(int bid, int ask) {
    return ask - bid;
}

int midTicks(int bid, int ask) {
    return bid + (ask - bid) / 2;
}

int main() {
    CHECK_EQ(spreadTicks(100, 102), 2);
    CHECK_EQ(spreadTicks(100, 100), 0);
    CHECK_EQ(midTicks(100, 102), 101);
    CHECK_EQ(midTicks(100, 101), 100);
    std::cout << g_checks << " checks, " << g_failures << " failed\n";
    return g_failures == 0 ? 0 : 1;
}

