#include <iostream>
#include <vector>

// The first version. / truncates toward zero, so -3 / 5 is 0, not -1.
int roundDownOld(int price, int tick) {
    return price / tick * tick;
}

// The fix: a negative price between two ticks steps one more tick down.
int roundDown(int price, int tick) {
    int ticks = price / tick;
    if (price % tick != 0 && price < 0) {
        --ticks;
    }
    return ticks * tick;
}

int main() {
    // Each case: price in cents, tick in cents, the expected result.
    const std::vector<std::vector<int>> cases = {
        {12, 5, 10},       // between ticks
        {10, 5, 10},       // exactly on a tick
        {0, 5, 0},         // zero
        {4, 5, 0},         // just below the first tick
        {-3, 5, -5},       // negative, between ticks
        {-10, 5, -10},     // negative, on a tick
        {-3763, 5, -3765}, // regression: the -37.63 settle of April 2020
    };
    int oldFailed = 0;
    int newFailed = 0;
    for (const auto& c : cases) {
        int price = c[0], tick = c[1], want = c[2];
        if (roundDownOld(price, tick) != want) {
            ++oldFailed;
            std::cout << "old roundDown(" << price << ", " << tick << ") = "
                      << roundDownOld(price, tick) << ", expected " << want << '\n';
        }
        if (roundDown(price, tick) != want) {
            ++newFailed;
            std::cout << "new roundDown(" << price << ", " << tick << ") = "
                      << roundDown(price, tick) << ", expected " << want << '\n';
        }
    }
    std::cout << "old: " << oldFailed << " of " << cases.size() << " failed\n";
    std::cout << "new: " << newFailed << " of " << cases.size() << " failed\n";
    return newFailed == 0 ? 0 : 1;
}

